def min_cost_brute(cost, i):
    if i >= len(cost):
        return 0
    return cost[i] + min(min_cost_brute(cost, i + 1), min_cost_brute(cost, i + 2))    # try BOTH choices

def min_cost_climbing_stairs_brute(cost):
    return min(min_cost_brute(cost, 0), min_cost_brute(cost, 1))

